const response = $input.first().json;
const content = response.choices[0].message.content;

let products = [];
try {
  // Limpiar markdown si viene envuelto en ```json ... ```
  const clean = content.replace(/```json\n?|```/g, '').trim();
  products = JSON.parse(clean);
} catch (e) {
  // Si no se puede parsear, guardar como error
  products = [{ name: 'Error al parsear respuesta', error: e.message, raw: content.substring(0, 500) }];
}

const date = new Date().toISOString().split('T')[0];
console.log(`[ProductResearch] ${date}: ${products.length} productos encontrados`);

return [{ json: { products, count: products.length, date } }];
